import {testIdProps} from '@github-ui/test-id-props'
import {InfoIcon, KebabHorizontalIcon, XIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Stack} from '@primer/react'
import {useState, useRef} from 'react'
import {NestingTableRow} from './NestingTable/NestingTableRow'
import {RemoveRoleAssignmentDialog} from './RemoveRoleAssignmentDialog'
import {RoleFgpsDialog} from './RoleFgpsDialog'
import type {ActorBasicMeta, RoleAssignment} from '../types/role-assignments'
import getRoleIcon from '../utils/RoleIconMap'
import styles from './RoleDetailsRow.module.css'
import {AllOrgsTokenComponent} from './AllOrgsTokenComponent'

export function RoleDetailsRow({
  actor,
  roleAssignment,
  viewerPermissions,
  allOrganizationAvatarURLs,
}: {
  actor: ActorBasicMeta
  roleAssignment: RoleAssignment
  viewerPermissions: {[permission: string]: boolean}
  allOrganizationAvatarURLs: string[]
}) {
  const role = roleAssignment.role

  const subDescription = roleAssignment.org_access && (
    <Stack direction="horizontal" gap="condensed">
      Assigned to:{' '}
      <AllOrgsTokenComponent
        roleName={role.name}
        orgAccess={roleAssignment.org_access}
        allOrganizationAvatarURLs={allOrganizationAvatarURLs}
      />
    </Stack>
  )

  return (
    <NestingTableRow
      leadingIcon={
        <span className="fgColor-muted" {...testIdProps('role-icon')}>
          {getRoleIcon(role.octicon)}
        </span>
      }
      title={role.name}
      description={<span>{role.description}</span>}
      subDescription={subDescription}
      trailingItems={[
        <RoleActionMenu
          key={`actions-role-${role.id}`}
          actor={actor}
          roleAssignment={roleAssignment}
          viewerPermissions={viewerPermissions}
        />,
      ]}
    />
  )
}

function RoleActionMenu({
  actor,
  roleAssignment,
  viewerPermissions,
}: {
  actor: ActorBasicMeta
  roleAssignment: RoleAssignment
  viewerPermissions: {[permission: string]: boolean}
}) {
  const role = roleAssignment.role
  const [showDetails, setShowDetails] = useState(false)
  const [showRemoveDialog, setShowRemoveDialog] = useState(false)
  const menuRef = useRef<HTMLButtonElement>(null)

  const removeContent = (
    <>
      <ActionList.Divider />
      <ActionList.Item variant="danger" onSelect={() => setShowRemoveDialog(true)}>
        <ActionList.LeadingVisual>
          <XIcon />
        </ActionList.LeadingVisual>
        Remove
      </ActionList.Item>
    </>
  )

  return (
    <>
      <ActionMenu anchorRef={menuRef}>
        <ActionMenu.Button
          className={styles.actionMenuButton}
          variant="invisible"
          aria-label={`Actions for ${role.name}`}
          trailingAction={null} // do not want menu triangle indicator, which is included by default
          ref={menuRef}
          {...testIdProps('role-action-menu')}
        >
          <KebabHorizontalIcon />
        </ActionMenu.Button>
        <ActionMenu.Overlay>
          <ActionList>
            <ActionList.Item onSelect={() => setShowDetails(true)}>
              <ActionList.LeadingVisual>
                <InfoIcon />
              </ActionList.LeadingVisual>
              Details
            </ActionList.Item>
            {viewerPermissions.write_enterprise_custom_enterprise_role && removeContent}
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>

      <RoleFgpsDialog role={role} show={showDetails} onClose={() => setShowDetails(false)} returnFocusRef={menuRef} />
      {viewerPermissions.write_enterprise_custom_enterprise_role && showRemoveDialog && (
        <RemoveRoleAssignmentDialog
          actor={actor}
          roleAssignment={roleAssignment}
          setOpen={setShowRemoveDialog}
          returnFocusRef={menuRef}
          canViewEnterpriseTeams
        />
      )}
    </>
  )
}
