import React from 'react'
import {Dialog} from '@primer/react/experimental'
import {OrganizationIcon, TasklistIcon, CircleSlashIcon} from '@primer/octicons-react'

interface OrganizationSelectionTypeConfirmationDialogProps {
  isOpen: boolean
  onClose: () => void
  onConfirm: () => void
  currentSelectionType: string
  newSelectionType: string
}

const getSelectionTypeInfo = (selectionType: string) => {
  switch (selectionType) {
    case 'all':
      return {
        icon: <OrganizationIcon />,
        name: 'All Organizations',
        description: 'This applies to all current and future organizations.',
      }
    case 'selected':
      return {
        icon: <TasklistIcon />,
        name: 'Specific Organizations',
        description: 'Select specific organizations for this team.',
      }
    case 'disabled':
      return {
        icon: <CircleSlashIcon />,
        name: 'None',
        description: 'Your team will not have any organization access.',
      }
    default:
      return {
        icon: null,
        name: 'Unknown',
        description: '',
      }
  }
}

const OrganizationSelectionTypeConfirmationDialog: React.FC<OrganizationSelectionTypeConfirmationDialogProps> = ({
  isOpen,
  onClose,
  onConfirm,
  currentSelectionType,
  newSelectionType,
}) => {
  const currentTypeInfo = getSelectionTypeInfo(currentSelectionType)
  const newTypeInfo = getSelectionTypeInfo(newSelectionType)

  const getImpactMessage = () => {
    if (currentSelectionType === 'all' && newSelectionType === 'selected') {
      return `This will limit the team's access to only the organizations you select.`
    }
    if (currentSelectionType === 'selected' && newSelectionType === 'all') {
      return `This will grant the team access to all current and future organizations automatically.`
    }
    if (newSelectionType === 'disabled') {
      return 'This will remove all organizations access for this team.'
    }
    return 'This will change the organization selection type for this team.'
  }

  return (
    <>
      {isOpen && (
        <Dialog
          title="Confirm access change"
          onClose={onClose}
          position={{narrow: 'bottom', regular: 'center'}}
          width="large"
          footerButtons={[
            {
              buttonType: 'default',
              content: 'Cancel',
              onClick: onClose,
            },
            {
              buttonType: 'primary',
              content: 'Confirm Change',
              onClick: onConfirm,
            },
          ]}
        >
          <div>
            You&apos;re about to change this team&apos;s access settings from <strong>{currentTypeInfo.name}</strong> to{' '}
            <strong>{newTypeInfo.name}</strong>.
          </div>

          <div className="tmp-mt-3">{getImpactMessage()}</div>
        </Dialog>
      )}
    </>
  )
}

export default OrganizationSelectionTypeConfirmationDialog
