import {useState} from 'react'
import type {ActionListItemInput as ItemInput} from '@primer/react/deprecated'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {TriangleDownIcon} from '@primer/octicons-react'
import {Button, SelectPanel, Tooltip, CounterLabel} from '@primer/react'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {useMutation, useQuery} from '@github-ui/react-query'
import {getQueryClient} from '@github-ui/react-core/query-client'
import {useDebounce} from '@github-ui/use-debounce'
import styles from '../styles/BusinessTeamMemberView.module.css'

export interface AddUserToTeamButtonProps {
  inactive: boolean
  enterpriseSlug: string
  teamSlug: string
  membersAllowedToAdd: number
  teamMembersLimit: number
  addMembersToTable: (newUser: User[]) => void
  onBannerMessage?: (message: string | null) => void
}

interface User {
  displayLogin: string
  id: number
  profileName: string
  avatarUrl: string
}

interface EligibleUsersData {
  totalEligibleUsersInEnterprise: number
  users: User[]
}

interface MutationResponse {
  bannerMessage?: string
}

const AddUserToTeamButton: React.FC<AddUserToTeamButtonProps> = payload => {
  const {addMembersToTable, inactive, membersAllowedToAdd, teamMembersLimit, onBannerMessage} = payload
  const [selectedUsers, setSelectedUsers] = useState<User[]>([])
  const [filter, setFilter] = useState('')
  const [debouncedFilter, setDebouncedFilter] = useState('')
  const [dropdownOpen, setDropdownOpen] = useState(false)
  const [addAllEnterpriseMembersSelected, setAddAllEnterpriseMembersSelected] = useState(false)
  const [totalSelectedWhenSelectAll, setTotalSelectedWhenSelectAll] = useState<number>(0)
  const pageSize = 30
  const canAddMoreUsers = membersAllowedToAdd > 0 && selectedUsers.length < membersAllowedToAdd

  const {
    isError: searchQueryError,
    isPending: searchQueryPending,
    data: searchResults,
  } = useQuery<EligibleUsersData>({
    queryKey: ['nonMembers', payload.enterpriseSlug, payload.teamSlug, debouncedFilter],
    queryFn: async () => {
      const params = new URLSearchParams({
        query: debouncedFilter,
        page_size: pageSize.toString(),
      })
      const response = await verifiedFetchJSON(
        `/enterprises/${payload.enterpriseSlug}/teams/${payload.teamSlug}/eligible_members?${params}`,
      )

      if (response.ok) {
        return await response.json()
      } else {
        throw new Error(`${response.status} on ${response.url}`)
      }
    },
    enabled: dropdownOpen,
  })
  const totalEligibleUsersInEnterprise: number = searchResults?.totalEligibleUsersInEnterprise || -1
  const nonMembers: User[] = searchResults?.users || []
  const usersToAddCount = addAllEnterpriseMembersSelected ? totalSelectedWhenSelectAll : selectedUsers.length

  const {
    mutate: saveMutation,
    isError: saveMutationIsError,
    error: saveMutationError,
    isPending: saveMutationPending,
  } = useMutation({
    mutationFn: async () => {
      const response = await verifiedFetchJSON(
        `/enterprises/${payload.enterpriseSlug}/teams/${payload.teamSlug}/members`,
        {
          method: 'POST',
          body: {
            select_all_in_enterprise: addAllEnterpriseMembersSelected,
            user_ids: addAllEnterpriseMembersSelected ? [] : selectedUsers.map(item => item.id),
          },
        },
      )

      let json
      try {
        json = await response.json()
      } catch {
        throw new Error()
      }
      if (response.ok) {
        return json
      }
      if (response.status >= 400 && response.status < 500) {
        throw new Error(json.error)
      }
      throw new Error()
    },
    onSuccess: async response => {
      addMembersToTable(selectedUsers)
      closeDropdown()
      setBannerMessage(response)
      await getQueryClient().invalidateQueries({queryKey: ['nonMembers', payload.enterpriseSlug, payload.teamSlug]})
    },
  })

  const setBannerMessage = (response: MutationResponse) => {
    if (onBannerMessage && response?.bannerMessage) {
      onBannerMessage(response.bannerMessage)
    }
  }

  function handleFilterChange(newFilter: string) {
    setFilter(newFilter)
    updateDebouncedFilter(newFilter)
  }

  const updateDebouncedFilter = useDebounce((newFilter: string) => {
    setDebouncedFilter(newFilter)
  }, 300)

  const items: ItemInput[] = [
    ...nonMembers.map((user, index) => ({
      id: user.id,
      text: user.displayLogin,
      description: user.profileName,
      disabled: !canAddMoreUsers && !selectedUsers.some(u => u.id === user.id),
      leadingVisual: () => <GitHubAvatar size={16} src={user.avatarUrl} alt={`${user.displayLogin}'s avatar`} />,
      'data-testid': `enterprise-member-${index}`,
      'aria-labelledby': `enterprise-member-${index}`,
    })),
  ]

  function closeDropdown() {
    setDropdownOpen(false)
    setSelectedUsers([])
    setFilter('')
    setDebouncedFilter('')
    setAddAllEnterpriseMembersSelected(false)
    setTotalSelectedWhenSelectAll(0)
  }

  function showDropdown() {
    setSelectedUsers([])
    setDropdownOpen(true)
  }

  return (
    <>
      {!membersAllowedToAdd ? (
        <Tooltip text={`Cannot add more members, team has reached the ${teamMembersLimit} member limit.`} direction="n">
          <Button data-testid="add-members-button" inactive>
            <span>Add members</span>
            <TriangleDownIcon className="ml-2" />
          </Button>
        </Tooltip>
      ) : (
        <SelectPanel
          id="add-members-dropdown"
          title="Select members"
          open={dropdownOpen}
          showSelectAll
          onOpenChange={setDropdownOpen}
          disableFullscreenOnNarrow
          items={items}
          selected={selectedUsers.map(user => ({id: user.id}))}
          onSelectedChange={(itemsList: ItemInput[]) => {
            const selectedItemIds = itemsList.map(item => item.id).filter((id): id is number => typeof id === 'number')
            const currentSelectedIds = selectedUsers.map(user => user.id)
            const visibleSelectedIds = currentSelectedIds.filter(id => nonMembers.some(user => user.id === id))

            // Handle bulk selection changes (like "Select All")
            if (selectedItemIds.length === 0) {
              // All items were deselected
              setSelectedUsers([])
              setAddAllEnterpriseMembersSelected(false)
            } else if (selectedItemIds.length === nonMembers.length && visibleSelectedIds.length === 0) {
              // All visible items were selected from an empty state (true "select all" for visible items)
              setSelectedUsers(nonMembers)
            } else {
              // Handle individual selections/deselections
              const addedIds = selectedItemIds.filter(id => !currentSelectedIds.includes(id))
              const removedIds = currentSelectedIds.filter(id => !selectedItemIds.includes(id))

              if (addedIds.length > 0) {
                // Add new selections
                const usersToAdd = nonMembers.filter(user => addedIds.includes(user.id))
                setSelectedUsers([...selectedUsers, ...usersToAdd])
              } else if (removedIds.length > 0) {
                // Remove deselections
                setSelectedUsers(selectedUsers.filter(user => !removedIds.includes(user.id)))
              }
            }
          }}
          filterValue={filter}
          onFilterChange={handleFilterChange}
          loading={saveMutationPending || searchQueryPending || filter !== debouncedFilter}
          placeholderText="Search members"
          renderAnchor={({id, ...anchorProps}) => (
            <Button
              id={id}
              data-testid="add-members-button"
              inactive={inactive}
              trailingAction={TriangleDownIcon}
              variant={inactive ? 'default' : 'primary'}
              onClick={showDropdown}
              {...anchorProps}
            >
              Add members
            </Button>
          )}
          secondaryAction={
            <div className="d-flex flex-justify-end" style={{width: '100%', padding: '3px'}}>
              <Button type="button" onClick={closeDropdown} size="small" style={{marginLeft: 'auto'}}>
                Cancel
              </Button>
              <Button
                inactive={selectedUsers.length > membersAllowedToAdd && !canAddMoreUsers}
                onClick={() => {
                  if (usersToAddCount > 0 && !(selectedUsers.length > membersAllowedToAdd && !canAddMoreUsers)) {
                    saveMutation()
                  } else {
                    closeDropdown()
                  }
                }}
                variant="primary"
                size="small"
                style={{marginLeft: '8px'}}
              >
                Add
                {usersToAddCount > 0 && (
                  <>
                    {' '}
                    <CounterLabel scheme="secondary" className={styles.addCounterLabel}>
                      {usersToAddCount}
                    </CounterLabel>
                  </>
                )}
              </Button>
            </div>
          }
          notice={
            searchQueryError || saveMutationIsError
              ? {
                  variant: 'error',
                  text:
                    (saveMutationIsError && saveMutationError?.message) || 'Something went wrong. Please try again.',
                }
              : selectedUsers.length > membersAllowedToAdd && !canAddMoreUsers
                ? {
                    variant: 'warning',
                    text: `The team member limit is ${teamMembersLimit}. Adjust your selection to add a new member.`,
                  }
                : !canAddMoreUsers
                  ? {
                      variant: 'warning',
                      text: `${teamMembersLimit}-team member limit reached. Please remove some members before adding more.`,
                    }
                  : debouncedFilter === '' &&
                      selectedUsers.length === pageSize &&
                      pageSize < totalEligibleUsersInEnterprise &&
                      addAllEnterpriseMembersSelected
                    ? {
                        variant: 'info',
                        text: (
                          <span style={{color: 'var(--fgColor-muted)'}}>
                            All {totalEligibleUsersInEnterprise} members are selected.{' '}
                            <Button
                              variant="link"
                              size="small"
                              data-testid="clear-all-button"
                              onClick={() => {
                                setAddAllEnterpriseMembersSelected(!addAllEnterpriseMembersSelected)
                                setTotalSelectedWhenSelectAll(0)
                              }}
                            >
                              Clear selection
                            </Button>{' '}
                            to adjust.
                          </span>
                        ),
                      }
                    : debouncedFilter === '' &&
                        selectedUsers.length === pageSize &&
                        pageSize < totalEligibleUsersInEnterprise &&
                        !addAllEnterpriseMembersSelected
                      ? {
                          variant: 'info',
                          text: (
                            <span style={{color: 'var(--fgColor-muted)'}}>
                              {selectedUsers.length} members are selected.{' '}
                              {totalEligibleUsersInEnterprise > membersAllowedToAdd ? (
                                <span>
                                  Can&apos;t select all {totalEligibleUsersInEnterprise} members. It exceeds the maximum
                                  team members limit.
                                </span>
                              ) : (
                                <Button
                                  onClick={() => {
                                    const newSelectAllState = !addAllEnterpriseMembersSelected
                                    setAddAllEnterpriseMembersSelected(newSelectAllState)
                                    if (newSelectAllState) {
                                      setTotalSelectedWhenSelectAll(totalEligibleUsersInEnterprise)
                                    } else {
                                      setTotalSelectedWhenSelectAll(0)
                                    }
                                  }}
                                  variant="link"
                                  size="small"
                                  data-testid="select-all-button"
                                  disabled={totalEligibleUsersInEnterprise > membersAllowedToAdd}
                                >
                                  Select all {totalEligibleUsersInEnterprise}
                                </Button>
                              )}
                            </span>
                          ),
                        }
                      : undefined
          }
          message={
            addAllEnterpriseMembersSelected
              ? {
                  variant: 'empty',
                  title: 'All enterprise members selected',
                  body: `You've selected all ${totalSelectedWhenSelectAll} eligible members`,
                }
              : nonMembers.length === 0
                ? debouncedFilter === ''
                  ? {
                      variant: 'empty',
                      title: 'No more enterprise members to add',
                      body: 'All members of your enterprise have been added to this team.',
                    }
                  : {
                      variant: 'empty',
                      title: 'No enterprise members found',
                      body: 'Try a different search term',
                    }
                : undefined
          }
          overlayProps={{
            width: 'medium',
            maxHeight: 'large',
          }}
        />
      )}
    </>
  )
}

export default AddUserToTeamButton
