import {useEffect, useState} from 'react'
import {Banner, Heading, Link, TextInput, FormControl, Pagination, Button, ConfirmationDialog} from '@primer/react'
import {clsx} from 'clsx'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {updateSearchParams} from '@github-ui/history'
import {Blankslate} from '@primer/react/experimental'
import {useDebounce} from '@github-ui/use-debounce'

type EnterpriseTeam = {
  id: number
  name: string
  memberCount: number
  showRoute: string
  canMembersBeRemoved: boolean
}

type EnterpriseTeamMember = {
  id: number
  name: string
  login: string
  showRoute: string
}

export interface StafftoolsBusinessTeamMembersPayload {
  // Update this type to reflect the data you place in payload in Rails
  totalEntries: number
  totalPages: number
  enterpriseTeam: EnterpriseTeam
  members: EnterpriseTeamMember[]
  businessSlug: string
}

export function StafftoolsBusinessTeamMembersView() {
  const payload = useRoutePayload<StafftoolsBusinessTeamMembersPayload>()
  const [urlSearchParams, setUrlSearchParams] = useState(() => new URLSearchParams(''))
  const [currentPage, setCurrentPage] = useState(1)
  const [searchboxValue, setSearchboxValue] = useState('')
  const [members, setMembers] = useState(payload.members)
  const [totalPages, setTotalPages] = useState(payload.totalPages)
  const [memberToRemove, setMemberToRemove] = useState<EnterpriseTeamMember | null>(null)
  const [successMessage, setSuccessMessage] = useState<string | null>(null)
  const [errorMessage, setErrorMessage] = useState<string | null>(null)

  useEffect(() => {
    const params = new URLSearchParams(location.search)
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setUrlSearchParams(params)
    setSearchboxValue(params.get('query') || '')
    setCurrentPage(parseInt(params.get('page') || '1'))
  }, [setUrlSearchParams, setSearchboxValue, setCurrentPage])

  const setSearchParam = (key: string, value: string) => {
    urlSearchParams.set(key, value)
    updateSearchParams(urlSearchParams)
  }

  const onPageChange: Parameters<typeof Pagination>['0']['onPageChange'] = (e, page) => {
    e.preventDefault()
    paginate(page)
  }

  const paginate = async (page: number): Promise<void> => {
    setSearchParam('page', page.toString())
    setCurrentPage(page)

    const result = await verifiedFetchJSON(
      `/stafftools/enterprises/${payload.businessSlug}/enterprise_teams/${
        payload.enterpriseTeam.id
      }/members?${urlSearchParams.toString()}`,
      {
        method: 'GET',
        headers: {Accept: 'application/json'},
      },
    )
    const data = await result.json()

    setMembers(data.members)
    setTotalPages(data.totalPages)
  }

  const handleSearchChange = (value: string) => {
    setSearchboxValue(value)
    debouncedSearch(value)
  }

  const debouncedSearch = useDebounce((searchValue: string) => {
    setSearchParam('query', searchValue)
    paginate(1)
  }, 300)

  const removeMember = async (member: EnterpriseTeamMember) => {
    const response = await verifiedFetchJSON(
      `/stafftools/enterprises/${payload.businessSlug}/enterprise_teams/${
        payload.enterpriseTeam.id
      }/members/${member.id}`,
      {
        method: 'DELETE',
        headers: {'Content-Type': 'application/json'},
      },
    )
    if (response.ok) {
      setErrorMessage(null)
      let message = `${member.login} is being removed from the ${payload.enterpriseTeam.name} enterprise team.`
      try {
        const body = await response.json()
        if (body?.data?.message) {
          message = body.data.message
        }
      } catch {
        // Response did not contain JSON; fall back to default message.
      }
      setSuccessMessage(message)
    } else {
      setSuccessMessage(null)
      let message = `Failed to remove ${member.login} from the ${payload.enterpriseTeam.name} enterprise team.`
      try {
        const body = await response.json()
        if (body?.data?.error) {
          message = body.data.error
        }
      } catch {
        // Response did not contain JSON; fall back to default message.
      }
      setErrorMessage(message)
    }
    paginate(currentPage)
  }

  return (
    <>
      {successMessage && (
        <Banner
          hideTitle
          title="Success"
          data-testid="flash-success"
          variant="success"
          className="tmp-mb-3"
          onDismiss={() => setSuccessMessage(null)}
        >
          {successMessage}
        </Banner>
      )}
      {errorMessage && (
        <Banner
          hideTitle
          title="Error"
          data-testid="flash-error"
          variant="critical"
          className="tmp-mb-3"
          onDismiss={() => setErrorMessage(null)}
        >
          {errorMessage}
        </Banner>
      )}
      <header className="Subhead">
        <Heading as="h2" className="Subhead-heading">
          <Link
            href={payload.enterpriseTeam.showRoute}
            data-testid={`team-link-${payload.enterpriseTeam.id}`}
            className={clsx('text-underline', 'tmp-mr-1')}
          >
            {payload.enterpriseTeam.name}
          </Link>
          / Members ({payload.totalEntries})
        </Heading>
      </header>
      {payload.totalEntries > 0 ? (
        <>
          <div className="d-flex tmp-mb-3">
            <FormControl>
              <FormControl.Label>Search members</FormControl.Label>
              <TextInput
                size="medium"
                placeholder="Find a member..."
                value={searchboxValue}
                onChange={e => handleSearchChange(e.target.value)}
                data-testid={`search-input`}
              />
            </FormControl>
          </div>
          <div>
            <table
              className="site-admin-table"
              style={{border: `var(--borderColor-default)`, borderRadius: `var(--borderRadius-medium)`}}
            >
              <thead>
                <tr>
                  <th style={{color: `var(--fgColor-default)`}}>Login</th>
                  <th style={{color: `var(--fgColor-default)`}}>Name</th>
                  <th style={{color: `var(--fgColor-default)`}}>Actions</th>
                </tr>
              </thead>
              <tbody>
                {members.length > 0 ? (
                  members.map((member: EnterpriseTeamMember) => (
                    <tr key={member.id}>
                      <td>
                        <Link href={member.showRoute} data-testid={`member-link-${member.id}`}>
                          {member.login}
                        </Link>
                      </td>
                      <td data-testid={`member-name-${member.id}`}>{member.name}</td>
                      <td>
                        <Button
                          onClick={() => setMemberToRemove(member)}
                          variant="danger"
                          size="small"
                          disabled={!payload.enterpriseTeam.canMembersBeRemoved}
                          data-testid={`remove-member-${member.id}`}
                          aria-label={`Remove ${member.login}`}
                        >
                          Remove
                        </Button>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan={3}>
                      <div className="fgColor-default">
                        <Blankslate>
                          <Blankslate.Heading>We couldn&apos;t find any matching members</Blankslate.Heading>
                          <Blankslate.Description>
                            No members matched your search criteria. Adjust your search to view results.
                          </Blankslate.Description>
                        </Blankslate>
                      </div>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
            {memberToRemove && (
              <ConfirmationDialog
                onClose={gesture => {
                  if (gesture === 'confirm') {
                    removeMember(memberToRemove)
                  }
                  setMemberToRemove(null)
                }}
                title="Remove enterprise team member"
                confirmButtonContent="Remove"
                confirmButtonType="danger"
                width="large"
              >
                <>
                  This will remove <b>{memberToRemove.login}</b> from the <b>{payload.enterpriseTeam.name}</b>{' '}
                  enterprise team. Please be sure you want to do this.
                </>
              </ConfirmationDialog>
            )}
          </div>
          {members.length > 0 && (
            <Pagination pageCount={totalPages} currentPage={currentPage} onPageChange={onPageChange} />
          )}
        </>
      ) : (
        <div className="fgColor-default">
          <Blankslate>
            <Blankslate.Heading>No members are in this enterprise team.</Blankslate.Heading>
          </Blankslate>
        </div>
      )}
    </>
  )
}
